package com.mchange.v2.c3p0.test.cfgcompat;

import java.io.File;
import java.io.FileOutputStream;
import java.io.OutputStreamWriter;
import java.io.Writer;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 *  One configuration situation: what is in c3p0.properties, what is in c3p0-config.xml, and what
 *  is on the command line as <code>-D</code>.
 *
 *  <p>Scenarios are generated by {@link #all}, in code rather than in a data file, because they
 *  have to be generated <i>identically</i> for the 0.14.2 baseline capture and for the
 *  comparison that runs against the current build. One generator means the two can't drift; a
 *  checked-in list of scenario files would have to be trusted to match the golden output it was
 *  captured with.</p>
 *
 *  <p>Only inputs <b>both</b> versions honor are used: <code>/c3p0.properties</code>,
 *  <code>/c3p0-config.xml</code>, and System properties. Nothing here depends on HOCON, on path
 *  files, or on anything else whose support differs between the two.</p>
 */
public final class ConfigScenario
{
    public final static String NAMED = "alpha";
    public final static String OTHER_NAMED = "beta";

    public final String name;

    /** Entries for /c3p0.properties, or empty for no such resource. */
    public final Map<String,String> propsFile;

    /** The body between &lt;c3p0-config&gt; tags, or null for no /c3p0-config.xml at all. */
    public final String xmlBody;

    /**
     *  A second XML document, written OUTSIDE the classpath and named by
     *  {@code com.mchange.v2.c3p0.cfg.xml}, or null for none.
     *
     *  <p>This is the axis the harness was missing. Under 0.14.x, naming a file in that property
     *  meant a classpath {@code /c3p0-config.xml} was ignored -- exactly one XML document was
     *  ever read. As of 0.15.0 both are read and merged, the named file winning key by key. The
     *  harness could not see that change because no scenario ever set the property.</p>
     */
    public final String externalXmlBody;

    /**
     *  Property names the classpath XML declares and the external file does not, so the keys
     *  0.14.2 would have discarded by reading only one document are nameable rather than
     *  guessed at. Empty unless both documents are present.
     */
    public final List<String> keysOnlyInClasspathXml;

    /** -D arguments. */
    public final Map<String,String> sysprops;

    /** Named configs the probe should interrogate, beyond the default and the undefined one. */
    public final List<String> namedScopes;

    private ConfigScenario( String name, Map<String,String> propsFile, String xmlBody,
                            Map<String,String> sysprops, List<String> namedScopes )
    { this( name, propsFile, xmlBody, null, Collections.<String>emptyList(), sysprops, namedScopes ); }

    private ConfigScenario( String name, Map<String,String> propsFile, String xmlBody,
                            String externalXmlBody, List<String> keysOnlyInClasspathXml,
                            Map<String,String> sysprops, List<String> namedScopes )
    {
        this.name                   = name;
        this.propsFile              = Collections.unmodifiableMap( new TreeMap<String,String>( propsFile ) );
        this.xmlBody                = xmlBody;
        this.externalXmlBody        = externalXmlBody;
        this.keysOnlyInClasspathXml = Collections.unmodifiableList( new ArrayList<String>( keysOnlyInClasspathXml ) );
        this.sysprops               = Collections.unmodifiableMap( new TreeMap<String,String>( sysprops ) );
        this.namedScopes            = Collections.unmodifiableList( new ArrayList<String>( namedScopes ) );
    }

    // ------------------------------------------------------------------ the axes

    /**
     *  An axis is a named set of contributions. A scenario is one choice from each axis, so the
     *  name of a scenario is the list of choices that produced it and is enough to reconstruct
     *  it by hand when a case fails.
     */
    private final static class Choice
    {
        final String label;
        final Map<String,String> props   = new LinkedHashMap<String,String>();
        final Map<String,String> syspops = new LinkedHashMap<String,String>();

        /**
         *  XML contributions are CHILDREN of a scope element, never whole documents, so that
         *  combining axes yields a document with exactly one &lt;default-config&gt; and exactly
         *  one &lt;named-config&gt;. Emitting an element per axis would instead produce duplicate
         *  scopes, and duplicate-scope handling is itself a thing that differs between versions
         *  -- which would quietly contaminate every comparison with a question nobody asked.
         */
        final List<String> xmlDefaultChildren = new ArrayList<String>();
        final List<String> xmlNamedChildren   = new ArrayList<String>();
        boolean declaresNamedScope = false;

        Choice( String label ) { this.label = label; }

        Choice prop( String k, String v )   { props.put( k, v ); return this; }
        Choice sysprop( String k, String v ){ syspops.put( k, v ); return this; }
        Choice xmlDefault( String x )       { xmlDefaultChildren.add( x ); return this; }
        Choice xmlNamed( String x )         { xmlNamedChildren.add( x ); declaresNamedScope = true; return this; }
        Choice declaresNamedScope()         { declaresNamedScope = true; return this; }
    }

    /** Default-scope pool properties: nowhere, properties, XML, or both in conflict. */
    private static List<Choice> defaultScopeAxis()
    {
        List<Choice> out = new ArrayList<Choice>();
        out.add( new Choice( "dflt-none" ) );
        out.add( new Choice( "dflt-props" ).prop( "c3p0.maxPoolSize", "15" ).prop( "c3p0.minPoolSize", "4" ) );
        out.add( new Choice( "dflt-xml" )
                 .xmlDefault( "<property name=\"maxPoolSize\">25</property>" )
                 .xmlDefault( "<property name=\"minPoolSize\">6</property>" ) );
        out.add( new Choice( "dflt-both" )
                 .prop( "c3p0.maxPoolSize", "15" ).prop( "c3p0.minPoolSize", "4" )
                 .xmlDefault( "<property name=\"maxPoolSize\">25</property>" )
                 .xmlDefault( "<property name=\"initialPoolSize\">7</property>" ) );
        return out;
    }

    /** The named config: absent, properties, XML, both in conflict, or declared-but-empty. */
    private static List<Choice> namedScopeAxis()
    {
        List<Choice> out = new ArrayList<Choice>();
        out.add( new Choice( "named-none" ) );
        out.add( new Choice( "named-props" )
                 .prop( "c3p0.named-configs." + NAMED + ".maxPoolSize", "31" )
                 .prop( "c3p0.named-configs." + NAMED + ".acquireIncrement", "5" ) );
        out.add( new Choice( "named-xml" )
                 .xmlNamed( "<property name=\"maxPoolSize\">41</property>" )
                 .xmlNamed( "<property name=\"acquireIncrement\">9</property>" ) );
        out.add( new Choice( "named-both" )
                 .prop( "c3p0.named-configs." + NAMED + ".maxPoolSize", "31" )
                 .prop( "c3p0.named-configs." + NAMED + ".propertyCycle", "11" )
                 .xmlNamed( "<property name=\"maxPoolSize\">41</property>" ) );
        out.add( new Choice( "named-xml-empty" ).declaresNamedScope() );
        return out;
    }

    /**
     *  User overrides for one user, in both the properties and the XML spelling.
     *
     *  <p>Both spellings are here on purpose, and they are not redundant. The XML spelling is
     *  the only one for which c3p0-0.14.2 produces an answer at all: a properties-style
     *  <code>c3p0.named-configs.X.user-overrides.USER.PROP</code> key makes 0.14.2's
     *  <code>findPropStyleNamedScopes</code> throw out of C3P0Config's class initializer, so the
     *  whole library is dead in that JVM (see the capture, and ConfigCompatJUnitTestCase). The
     *  XML cases are therefore the ones that carry a usable baseline for cross-scope merging --
     *  which is exactly where the one intended behaviour change lives.</p>
     */
    private static List<Choice> userOverridesAxis()
    {
        List<Choice> out = new ArrayList<Choice>();
        out.add( new Choice( "uo-none" ) );
        out.add( new Choice( "uo-default-props" )
                 .prop( "c3p0.user-overrides.steve.maxPoolSize", "7" )
                 .prop( "c3p0.user-overrides.steve.minPoolSize", "2" ) );
        out.add( new Choice( "uo-default-xml" )
                 .xmlDefault( "<user-overrides user=\"steve\">" +
                              "<property name=\"maxPoolSize\">20</property>" +
                              "<property name=\"minPoolSize\">5</property>" +
                              "</user-overrides>" ) );
        out.add( new Choice( "uo-named-xml" )
                 .xmlNamed( "<user-overrides user=\"steve\">" +
                            "<property name=\"maxPoolSize\">99</property>" +
                            "</user-overrides>" ) );
        // THE divergence: one user named in both scopes, each setting different properties.
        // 0.14.2 replaced steve's whole override set from the named scope, losing minPoolSize.
        out.add( new Choice( "uo-both-xml" )
                 .xmlDefault( "<user-overrides user=\"steve\">" +
                              "<property name=\"maxPoolSize\">20</property>" +
                              "<property name=\"minPoolSize\">5</property>" +
                              "</user-overrides>" )
                 .xmlNamed( "<user-overrides user=\"steve\">" +
                            "<property name=\"maxPoolSize\">99</property>" +
                            "</user-overrides>" ) );
        out.add( new Choice( "uo-two-users-xml" )
                 .xmlDefault( "<user-overrides user=\"steve\">" +
                              "<property name=\"maxPoolSize\">20</property>" +
                              "</user-overrides>" )
                 .xmlDefault( "<user-overrides user=\"alice\">" +
                              "<property name=\"maxPoolSize\">21</property>" +
                              "</user-overrides>" )
                 .xmlNamed( "<user-overrides user=\"alice\">" +
                            "<property name=\"minPoolSize\">3</property>" +
                            "</user-overrides>" ) );
        return out;
    }

    /** Extensions, whose names are never corrected and whose scoping replaces rather than merges. */
    private static List<Choice> extensionsAxis()
    {
        List<Choice> out = new ArrayList<Choice>();
        out.add( new Choice( "ext-none" ) );
        out.add( new Choice( "ext-default-props" )
                 .prop( "c3p0.extensions.initSql", "SET SCHEMA dflt" )
                 .prop( "c3p0.extensions.maxPoolSize", "not-a-pool-property" ) );
        out.add( new Choice( "ext-named-props" )
                 .prop( "c3p0.named-configs." + NAMED + ".extensions.initSql", "SET SCHEMA named" ) );
        out.add( new Choice( "ext-both-props" )
                 .prop( "c3p0.extensions.initSql", "SET SCHEMA dflt" )
                 .prop( "c3p0.named-configs." + NAMED + ".extensions.other", "value" ) );
        out.add( new Choice( "ext-xml-both" )
                 .xmlDefault( "<extensions><property name=\"initSql\">SET SCHEMA xdflt</property></extensions>" )
                 .xmlNamed( "<extensions><property name=\"initSql\">SET SCHEMA xnamed</property></extensions>" ) );
        return out;
    }

    /** System properties, which outrank resources in both versions. */
    private static List<Choice> syspropAxis()
    {
        List<Choice> out = new ArrayList<Choice>();
        out.add( new Choice( "sys-none" ) );
        out.add( new Choice( "sys-pool" ).sysprop( "c3p0.maxPoolSize", "99" ) );
        out.add( new Choice( "sys-named" ).sysprop( "c3p0.named-configs." + NAMED + ".maxPoolSize", "77" ) );
        out.add( new Choice( "sys-uo" ).sysprop( "c3p0.user-overrides.steve.maxPoolSize", "88" ) );
        return out;
    }

    /**
     *  The properties-style named-scope user override, swept once rather than crossed.
     *
     *  <p>Crossing it would cost twenty JVMs to record the same 0.14.2 crash twenty times. Swept
     *  once, it still pins that the current build reads these keys, and that 0.14.2 could not.</p>
     */
    private static List<Choice> propStyleNamedUserOverrideAxis()
    {
        List<Choice> out = new ArrayList<Choice>();
        out.add( new Choice( "pnuo-named-only" )
                 .prop( "c3p0.named-configs." + NAMED + ".user-overrides.steve.maxPoolSize", "9" ) );
        out.add( new Choice( "pnuo-both-scopes" )
                 .prop( "c3p0.user-overrides.steve.maxPoolSize", "7" )
                 .prop( "c3p0.user-overrides.steve.minPoolSize", "2" )
                 .prop( "c3p0.named-configs." + NAMED + ".user-overrides.steve.maxPoolSize", "9" ) );
        out.add( new Choice( "pnuo-two-users" )
                 .prop( "c3p0.user-overrides.alice.maxPoolSize", "8" )
                 .prop( "c3p0.named-configs." + NAMED + ".user-overrides.alice.minPoolSize", "3" )
                 .prop( "c3p0.named-configs." + NAMED + ".user-overrides.steve.maxPoolSize", "9" ) );
        return out;
    }

    // ------------------------------------------------------------------ the set

    /**
     *  The scenario set: the default-scope, named-config and user-override axes crossed in full,
     *  with the extension, System-property and properties-style-named-user-override axes swept
     *  separately against a fixed middle.
     *
     *  <p>Those three are crossed because they interact -- scope resolution, fall-through to the
     *  default config, and per-user merging all meet in the same code. Extensions and System
     *  properties do not interact with them in any way scope resolution can see (extensions live
     *  in their own sub-namespace; a System property is just another layer), so sweeping them
     *  costs a fifth of the JVMs and loses nothing a crossed run would have caught.</p>
     */
    public static List<ConfigScenario> all()
    {
        List<ConfigScenario> out = new ArrayList<ConfigScenario>();

        // hoisted, because each axis method builds fresh Choice objects: comparing choices
        // from two separate calls by identity would admit the baseline combination three times
        List<Choice> dflts = defaultScopeAxis();
        List<Choice> named = namedScopeAxis();
        List<Choice> uos   = userOverridesAxis();
        List<Choice> exts  = extensionsAxis();
        List<Choice> syses = syspropAxis();

        Choice extBase = exts.get( 0 );   // ext-none
        Choice sysBase = syses.get( 0 );  // sys-none

        for ( Choice d : dflts )
            for ( Choice n : named )
                for ( Choice u : uos )
                    out.add( combine( d, n, u, extBase, sysBase ) );

        Choice dBase = dflts.get( 1 );    // dflt-props
        Choice nBase = named.get( 1 );    // named-props
        Choice uBase = uos.get( 1 );      // uo-default-props

        for ( Choice e : exts )
            if ( e != extBase ) out.add( combine( dBase, nBase, uBase, e, sysBase ) );

        for ( Choice sy : syses )
            if ( sy != sysBase ) out.add( combine( dBase, nBase, uBase, extBase, sy ) );

        for ( Choice pn : propStyleNamedUserOverrideAxis() )
            out.add( combine( dBase, nBase, pn, extBase, sysBase ) );

        // appended last, so that adding them leaves every earlier scenario's name -- and so its
        // captured answers -- exactly as they were
        out.addAll( externalXmlScenarios() );

        return Collections.unmodifiableList( out );
    }

    private static ConfigScenario combine( Choice... choices )
    {
        StringBuilder name = new StringBuilder();
        Map<String,String> props = new LinkedHashMap<String,String>();
        Map<String,String> sys   = new LinkedHashMap<String,String>();
        List<String> defaultChildren = new ArrayList<String>();
        List<String> namedChildren   = new ArrayList<String>();
        boolean declaresNamed = false;

        for ( Choice c : choices )
        {
            if ( name.length() > 0 ) name.append( '.' );
            name.append( c.label );
            props.putAll( c.props );
            sys.putAll( c.syspops );
            defaultChildren.addAll( c.xmlDefaultChildren );
            namedChildren.addAll( c.xmlNamedChildren );
            declaresNamed = declaresNamed || c.declaresNamedScope;
        }

        String xmlBody = assembleXml( defaultChildren, namedChildren, declaresNamed );

        // every scenario asks about both named configs: one that choices may define, and one
        // that nothing ever defines, alongside the undefined name the probe adds for itself
        return new ConfigScenario( name.toString(), props, xmlBody, sys,
                                   java.util.Arrays.asList( NAMED, OTHER_NAMED ) );
    }

    /**
     *  Exactly one &lt;default-config&gt; and at most one &lt;named-config&gt;, or null when no
     *  axis contributed XML at all -- in which case no c3p0-config.xml is written, which is
     *  itself one of the situations under test.
     */
    private static String assembleXml( List<String> defaultChildren, List<String> namedChildren, boolean declaresNamed )
    {
        if ( defaultChildren.isEmpty() && namedChildren.isEmpty() && ! declaresNamed ) return null;

        StringBuilder sb = new StringBuilder();
        if (! defaultChildren.isEmpty() )
        {
            sb.append( "  <default-config>\n" );
            for ( String child : defaultChildren ) sb.append( "    " ).append( child ).append( '\n' );
            sb.append( "  </default-config>\n" );
        }
        if ( declaresNamed || ! namedChildren.isEmpty() )
        {
            if ( namedChildren.isEmpty() )
                sb.append( "  <named-config name=\"" ).append( NAMED ).append( "\"/>\n" );
            else
            {
                sb.append( "  <named-config name=\"" ).append( NAMED ).append( "\">\n" );
                for ( String child : namedChildren ) sb.append( "    " ).append( child ).append( '\n' );
                sb.append( "  </named-config>\n" );
            }
        }
        return sb.toString();
    }

    /**
     *  The {@code com.mchange.v2.c3p0.cfg.xml} axis: an XML document found by path rather than as
     *  a resource, with and without a classpath document alongside it.
     *
     *  <p>Three situations, and the third is the one that matters. With only the external file,
     *  both versions read the same single document and must agree. With only the classpath file,
     *  likewise. With <b>both</b>, 0.14.2 read only the external one and discarded the resource
     *  entirely, where 0.15.0 merges them with the external file winning key by key -- the
     *  adopted change, and the one no scenario could previously see.</p>
     *
     *  <p>The two documents in the "both" cases declare <b>disjoint</b> property names on
     *  purpose. Overlapping names would resolve to the external file's value under either
     *  version and so prove nothing; disjoint ones make every difference an addition whose key
     *  can be named in advance, which is what lets the comparison exempt the change narrowly
     *  instead of waving the scenario through.</p>
     */
    private static List<ConfigScenario> externalXmlScenarios()
    {
        List<ConfigScenario> out = new ArrayList<ConfigScenario>();

        String externalDefault =
            "  <default-config>\n" +
            "    <property name=\"maxPoolSize\">61</property>\n" +
            "    <property name=\"acquireIncrement\">6</property>\n" +
            "  </default-config>\n";

        String externalWithNamed = externalDefault +
            "  <named-config name=\"" + NAMED + "\">\n" +
            "    <property name=\"maxPoolSize\">62</property>\n" +
            "  </named-config>\n";

        // disjoint from the external document above, so a surviving key names itself
        String classpathDisjoint =
            "  <default-config>\n" +
            "    <property name=\"minPoolSize\">2</property>\n" +
            "    <property name=\"maxStatements\">33</property>\n" +
            "  </default-config>\n";

        String classpathDisjointWithNamed = classpathDisjoint +
            "  <named-config name=\"" + NAMED + "\">\n" +
            "    <property name=\"minPoolSize\">3</property>\n" +
            "  </named-config>\n";

        out.add( external( "extxml-only", null, externalDefault, NONE ) );
        out.add( external( "extxml-only-with-named", null, externalWithNamed, NONE ) );

        out.add( external( "extxml-and-classpath", classpathDisjoint, externalDefault,
                           Arrays.asList( "minPoolSize", "maxStatements" ) ) );
        out.add( external( "extxml-and-classpath-named", classpathDisjointWithNamed, externalWithNamed,
                           Arrays.asList( "minPoolSize", "maxStatements" ) ) );

        // and one where the two documents AGREE on a key, which must resolve the same either way
        out.add( external( "extxml-overlapping", 
                           "  <default-config><property name=\"maxPoolSize\">99</property></default-config>\n",
                           externalDefault, NONE ) );

        // the external file alongside properties-style config, to pin that the ordering between
        // them is unchanged: XML still outranks /c3p0.properties
        Map<String,String> props = new java.util.LinkedHashMap<String,String>();
        props.put( "c3p0.maxPoolSize", "15" );
        props.put( "c3p0.checkoutTimeout", "4000" );
        out.add( new ConfigScenario( "extxml-over-properties", props, null, externalDefault, NONE,
                                     Collections.<String,String>emptyMap(),
                                     Arrays.asList( NAMED, OTHER_NAMED ) ) );

        return out;
    }

    private final static List<String> NONE = Collections.<String>emptyList();

    private static ConfigScenario external( String name, String classpathXml, String externalXml,
                                            List<String> keysOnlyInClasspathXml )
    {
        return new ConfigScenario( name, Collections.<String,String>emptyMap(), classpathXml,
                                   externalXml, keysOnlyInClasspathXml,
                                   Collections.<String,String>emptyMap(),
                                   Arrays.asList( NAMED, OTHER_NAMED ) );
    }

    // ------------------------------------------------------------------ materializing

    /**
     *  Writes this scenario's resources into <code>dir</code>, which becomes a classpath entry.
     *
     *  <p>Note that two separate <code>&lt;default-config&gt;</code> or
     *  <code>&lt;named-config&gt;</code> elements can arrive here from two different axes. That is
     *  not a flaw in the generator -- c3p0 merges duplicate scopes in document order -- but it is
     *  worth knowing when reading a failure, since the XML will not look the way any single axis
     *  wrote it.</p>
     */
    public List<String> materialize( File dir ) throws Exception
    {
        if (! dir.isDirectory() && ! dir.mkdirs() )
            throw new Exception( "Could not create scenario directory " + dir );

        if (! propsFile.isEmpty() )
        {
            Writer w = writer( new File( dir, "c3p0.properties" ) );
            try
            {
                for ( Map.Entry<String,String> entry : propsFile.entrySet() )
                    w.write( entry.getKey() + "=" + entry.getValue() + "\n" );
            }
            finally { w.close(); }
        }

        if ( xmlBody != null ) writeXml( new File( dir, "c3p0-config.xml" ), xmlBody );

        List<String> extraSysprops = new ArrayList<String>();
        if ( externalXmlBody != null )
        {
            // deliberately NOT in dir: dir is a classpath entry, and the point of this document
            // is that it is found by path rather than as a resource
            File externalDir = new File( dir.getParentFile(), dir.getName() + "-external" );
            if (! externalDir.isDirectory() && ! externalDir.mkdirs() )
                throw new Exception( "Could not create external-XML directory " + externalDir );

            File external = new File( externalDir, "c3p0-config.xml" );
            writeXml( external, externalXmlBody );
            extraSysprops.add( "-Dcom.mchange.v2.c3p0.cfg.xml=" + external.getAbsolutePath() );
        }
        return extraSysprops;
    }

    private static void writeXml( File f, String body ) throws Exception
    {
        Writer w = writer( f );
        try { w.write( "<c3p0-config>\n" + body + "</c3p0-config>\n" ); }
        finally { w.close(); }
    }

    private static Writer writer( File f ) throws Exception
    { return new OutputStreamWriter( new FileOutputStream( f ), "UTF-8" ); }

    public List<String> syspropArgs()
    {
        List<String> out = new ArrayList<String>();
        for ( Map.Entry<String,String> entry : sysprops.entrySet() )
            out.add( "-D" + entry.getKey() + "=" + entry.getValue() );
        return out;
    }

    @Override
    public String toString()
    { return name; }
}
